[4735] = { en = "Egg Collection", tier = 4,
  t = "Eieren verzamelen",
  d = "$N, eindelijk ben ik klaar voor echte monsters van drakeneieren! Hier, neem deze Collectronic Module. Hij is gemaakt om een drakenei los te halen en klaar te maken voor vervoer. Ga terug naar de Rookery en gebruik de module om eieren te verzamelen.$B$BEn vergeet niet ze eerst te bevriezen, anders komen ze misschien uit voordat je ze kunt verzamelen!$B$BBreng ze naar mij als je genoeg eieren hebt!",
  o = "Breng 8 Collected Dragon Eggs en de Collectronic Module naar Tinkee Steamboil bij Flame Crest in de Burning Steppes.",
  p = "Heb je de eieren, $N? Mijn beschermheer hoorde dat je ze voor mij verzamelt, en hij wil ze heel graag in handen krijgen!",
  c = "Wauw, het is je gelukt! De Collectronic Module werkte! Ik ben een genie!$B$BDank je, $N. Mijn beschermheer zal erg blij zijn met deze eieren...",
  g = { {"monsters", "samples (monster)"}, {"drakeneieren", "dragon eggs (drakenei)"}, {"los te halen", "to extract (loshalen)"}, {"vervoer", "transport"}, {"bevriezen", "to freeze"}, {"komen ... uit", "hatch (uitkomen)"}, {"beschermheer", "patron"}, {"in handen krijgen", "to get hold of"}, {"genie", "genius"} },
},

[4742] = { en = "Seal of Ascension", tier = 4,
  t = "Het Seal of Ascension",
  d = "Zoals je ziet, heeft het onversierde zegel drie lege openingen. In elke opening moet een edelsteen komen die het gezag van de leiders voorstelt. Ten slotte moet Overlord Wyrmthalak, meester van de lagere citadel, het zegel smeden in de vlammen van de Black Dragonflight.$B$BBegrijp dit goed, sterveling: de kans is klein dat een van de drie generaals van de lagere citadel op een bepaald moment een edelsteen bij zich heeft. Je moet waakzaam zijn tijdens je zoektocht. Blijf vastberaden!",
  o = "Vind de drie edelstenen van gezag: The Gemstone of Smolderthorn, Gemstone of Spirestone en Gemstone of Bloodaxe. Breng ze samen met het Unadorned Seal of Ascension terug naar Vaelan.$B$BDe generaals zijn volgens Vaelan: War Master Voone van de Smolderthorn, Highlord Omokk van de Spirestone en Overlord Wyrmthalak van de Bloodaxe.",
  p = "Moed en geduld boven alles, $N!",
  c = "<Het beeld van Vaelan wordt even wazig.>$B$B<De stukken die je had verzameld, zijn verdwenen.>$B$BHet Unforged Seal of Ascension is nu klaar. Het is tijd voor de laatste stap.",
  g = { {"onversierde", "unadorned (onversierd)"}, {"zegel", "seal"}, {"openingen", "sockets, openings (opening)"}, {"edelsteen", "gemstone"}, {"gezag", "authority, command"}, {"voorstelt", "represents (voorstellen)"}, {"smeden", "to forge"}, {"sterveling", "mortal"}, {"waakzaam", "vigilant"}, {"vastberaden", "determined"}, {"wazig", "blurry"} },
},

[4743] = { en = "Seal of Ascension", tier = 4,
  t = "Het Seal of Ascension",
  d = "Afgezien van die in de bovenste citadel kunnen maar weinig zwarte drakenwezens het zegel smeden met hun eigen vurige adem. Wyrmthalak is zo'n drakenwezen, maar zijn wil is onbreekbaar.$B$BJe moet naar de Wyrmbog in Dustwallow Marsh reizen. Daar vind je een oeroude draak die Emberstrife heet. Je moet zijn wil breken, $N. Breek die en gebruik deze bol op zijn verzwakte lichaam. Je hebt maar een paar seconden om zijn geest te beheersen en de vlammen aan te wakkeren die het zegel zullen smeden.",
  o = "Reis naar de Wyrmbog in Dustwallow Marsh. Zoek de oeroude draak Emberstrife en sla hem zonder genade, tot zijn wil gebroken is.$B$BOp dat moment moet je het Unforged Seal of Ascension voor het grote beest neerleggen. Daarna moet je snel de Orb of Draconic Energy op zijn verzwakte lichaam gebruiken en de macht over zijn geest overnemen. Beheers het beest en dwing de Flames of the Black Dragonflight op het Unforged Seal of Ascension!",
  p = "Verspil geen tijd, $N. Nefarian werkt koortsachtig om zijn kwaad op onze wereld los te laten.",
  c = "Blijf stilstaan terwijl ik de laatste beschermingsspreuk uitspreek.$B$B<De ogen van Vaelan veranderen in twee bollen van vuur.>$B$BHet Seal of Ascension is klaar...$B$BWeet dit: ik heb het voorwerp krachtige beschermende spreuken gegeven. In je donkerste uur, als alles verloren lijkt, staat de kracht van de rode vlucht tot je beschikking.",
  g = { {"afgezien van", "apart from"}, {"drakenwezens", "dragonkin (drakenwezen)"}, {"onbreekbaar", "unbreakable"}, {"oeroude", "ancient (oeroud)"}, {"verzwakte", "weakened (verzwakt)"}, {"beheersen", "to control"}, {"aan te wakkeren", "to fan (aanwakkeren)"}, {"zonder genade", "without mercy"}, {"koortsachtig", "feverishly"}, {"beschermingsspreuk", "protective spell"}, {"tot je beschikking", "at your disposal"} },
},

[4764] = { en = "Doomrigger's Clasp", tier = 4,
  t = "De gesp van Doomrigger",
  d = "Hoog in Blackrock Spire is een zaal die vroeger de Hall of Fortune heette. Daar bewaarden de Dark Iron-dwergen hun relikwieën, trofeeën en kunstvoorwerpen.$B$BDat is lang geleden. Men zegt dat de zaal is ingestort en nu wordt gebruikt voor... minder nette zaken. Maar ik denk dat daar nog enkele oude dwergenrelikwieën te vinden zijn.$B$BEen van die relikwieën is de gesp van Doomrigger. Het oppervlak zit zo vol zeldzame edelstenen dat elke dwerg die ernaar kijkt, ervan moet huilen, zei men.$B$BDie gesp, $N, is je doel.",
  o = "Breng Doomrigger's Clasp naar Mayara Brightwing in de Burning Steppes.",
  p = "Heb je de gesp, $N? Mijn beschermheer betaalt er heel goed voor.",
  c = "Je hebt hem gevonden! Dus de geruchten waren waar!$B$BDank je, $N. Mijn beschermheer, Count Remington Ridgewell, zal heel blij zijn met deze aanvulling op zijn verzameling.",
  g = { {"gesp", "clasp"}, {"relikwieën", "relics (relikwie)"}, {"kunstvoorwerpen", "objects of art (kunstvoorwerp)"}, {"ingestort", "collapsed (instorten)"}, {"oppervlak", "surface"}, {"zeldzame", "rare (zeldzaam)"}, {"geruchten", "rumours (gerucht)"}, {"aanvulling", "addition"}, {"verzameling", "collection"} },
},

[4765] = { en = "Delivery to Ridgewell", tier = 4,
  t = "Levering aan Ridgewell",
  d = "Ik heb de gesp van Doomrigger in een kist verpakt die naar Stormwind verstuurd kan worden. $N, je bent enorm behulpzaam geweest. Mag ik je nog om één laatste gunst vragen?$B$BBreng de kist naar Count Remington Ridgewell. Je vindt hem in de Keep of Stormwind. Ik weet zeker dat hij heel blij zal zijn met wat je voor hem hebt.",
  o = "Breng Ridgewell's Crate naar Remington Ridgewell in Stormwind.",
  p = "Er werd me verteld dat er een boodschapper zou komen. Iemand met een geschenk uit Blackrock Spire.$B$BBen jij $ghij:zij;?",
  c = "Ah, dus jij bent $ghij:zij;! Je hebt mijn dank, $N. En... als je het nog niet wist... de dankbaarheid van een edelman uit het huis Ridgewell is bijna een koninklijk losgeld waard.",
  g = { {"levering", "delivery"}, {"verpakt", "packed (verpakken)"}, {"verstuurd", "shipped, sent (versturen)"}, {"behulpzaam", "helpful"}, {"gunst", "favour"}, {"boodschapper", "messenger"}, {"dankbaarheid", "gratitude"}, {"edelman", "nobleman"}, {"losgeld", "ransom"} },
},

[4766] = { en = "Mayara Brightwing", tier = 4,
  t = "Mayara Brightwing",
  d = "Een van mijn agenten, Mayara Brightwing, is naar de Burning Steppes gestuurd om de verwoeste stad Thaurissan te verkennen. Die vernietigde stad van de Dark Iron-dwergen verbergt misschien voorwerpen van grote waarde... voorwerpen die mooi in ons familiemuseum zouden passen.$B$BMayara zegt dat ze iets heeft gevonden en hulp nodig heeft om het op te halen, maar het ligt niet in Thaurissan. Er is juist een tocht naar Blackrock Spire nodig.$B$BIk ken de details niet, maar als je interesse hebt, spreek dan met Mayara in de Burning Steppes.",
  o = "Spreek met Mayara Brightwing in de Burning Steppes.",
  c = "Kom je uit Stormwind? Geweldig! Ik weet van een kunstvoorwerp waarvoor Remington zou moorden om het in zijn museum te hebben, maar het eruit halen wordt niet makkelijk.$B$BDaar kom jij in beeld.",
  g = { {"verwoeste", "ruined (verwoest)"}, {"verkennen", "to scout"}, {"vernietigde", "destroyed (vernietigd)"}, {"waarde", "value"}, {"familiemuseum", "family museum"}, {"tocht", "journey, foray"}, {"moorden", "to kill, murder"}, {"kom jij in beeld", "you come in"} },
},

[4866] = { en = "Mother's Milk", tier = 4,
  t = "Moedermelk",
  d = "Het is waarschijnlijk een van de sterkste giffen ter wereld, $r!$B$BTijdens mijn uitstapjes in de Spire heb ik de Blackrock horen praten over hoe dodelijk het is. Ze noemen het 'Moedermelk', naar Mother Smolderweb, de grote, gemene spin in de Skitterweb-grot.$B$BDit is wat ik van je nodig heb: een levend monster van de Melk, dat door JOUW aderen stroomt. Alleen de klier brengen is niet genoeg! Zorg dat ze je vergiftigt en kom terug naar mij!$B$BDan... mag ik jou melken!$B$B<Hij wrijft vol verwachting in zijn handen.>",
  o = "In het hart van Blackrock Spire vind je Mother Smolderweb. Val haar aan en zorg dat ze je vergiftigt. Grote kans dat je haar ook moet doden. Ga terug naar Ragged John als je vergiftigd bent, zodat hij je kan 'melken'.",
  p = "<Ragged John knijpt in je.>",
  c = "Dit wordt het beste bier ooit!$B$BEh, waar dacht jij dat ik dit voor ging gebruiken? Voor gif of zo??$B$BGekke kinderen...",
  e = "Gemolken",
  g = { {"giffen", "poisons (gif)"}, {"uitstapjes", "trips, jaunts (uitstapje)"}, {"dodelijk", "deadly"}, {"gemene", "nasty (gemeen)"}, {"aderen", "veins (ader)"}, {"klier", "gland"}, {"vergiftigt", "poisons (vergiftigen)"}, {"melken", "to milk"}, {"vol verwachting", "in anticipation"}, {"knijpt", "pinches (knijpen)"}, {"gemolken", "milked (melken)"} },
},

[4867] = { en = "Urok Doomhowl", tier = 4,
  t = "Urok Doomhowl",
  d = "Argh! Zo moeilijk om te praten!$B$BNeem dit briefje! Haal mijn mojo voor me!",
  o = "Lees Warosh's Scroll. Breng Warosh's Mojo naar Warosh.",
  p = "Ah! Heb je mijn mojo?",
  c = "Aha! Ik voel mijn krachten al terugkomen. En mijn geest wordt niet meer gekweld door de vloek van Urok.$B$BDank je, $N! Nederigheid is beneden mijn waardigheid, maar ik moet je hulp erkennen.$B$BEn ik wens je geluk op je tochten door Blackrock Spire. Je bent een dwaas als je denkt dat je de top kunt bereiken, maar aan je moed twijfelt niemand.",
  g = { {"briefje", "note"}, {"gekweld", "tormented (kwellen)"}, {"vloek", "curse"}, {"nederigheid", "humility"}, {"beneden mijn waardigheid", "beneath me"}, {"erkennen", "to acknowledge"}, {"dwaas", "fool"}, {"twijfelt", "doubts (twijfelen)"} },
},

[4903] = { en = "Warlord's Command", tier = 4,
  t = "Het bevel van de krijgsheer",
  d = "In opdracht van Warlord Goretooth moeten de volgende bewoners van Blackrock Spire vernietigd worden:$B$BDe dikke bedreiging, Highlord Omokk.$B$BDe wrede en meedogenloze trol, War Master Voone.$B$BOverlord Wyrmthalak, opzichter van de lagere stad.$B$BJe moet ook alle belangrijke documenten terugbrengen die je vindt.$B$BSlaag en word geëerd.$B$BFaal en word vergeten.",
  o = "Dood Highlord Omokk, War Master Voone en Overlord Wyrmthalak. Haal Important Blackrock Documents op. Ga terug naar Warlord Goretooth in Kargath als de missie is volbracht.",
  p = "<Warlord Goretooth salueert.>",
  c = "<De doffe groene huid van Warlord Goretooth wordt heel even bleekwit.>",
  g = { {"krijgsheer", "warlord"}, {"in opdracht van", "by order of"}, {"bewoners", "inhabitants (bewoner)"}, {"bedreiging", "menace, threat"}, {"meedogenloze", "ruthless (meedogenloos)"}, {"opzichter", "taskmaster"}, {"geëerd", "honoured (eren)"}, {"faal", "fail (falen)"}, {"volbracht", "accomplished (volbrengen)"}, {"salueert", "salutes (salueren)"}, {"doffe", "dull (dof)"}, {"bleekwit", "pasty white"} },
},

[4907] = { en = "Tinkee Steamboil", tier = 4,
  t = "Tinkee Steamboil",
  d = "Hoi, $N. Weet je Tinkee Steamboil nog? Nou, zij weet jou nog! Ze heeft me een bericht gestuurd dat ik naar je moest uitkijken, omdat... ze je hulp weer nodig heeft. Ik denk dat het iets te maken heeft met haar onderzoek naar draken.$B$BJe moet met haar praten in de Burning Steppes, bij Flame Crest.",
  o = "Spreek met Tinkee Steamboil.",
  c = "Felnok had gelijk! Ik heb je hulp echt weer nodig, en deze keer... wordt het heel gevaarlijk.$b$bBen je er klaar voor??",
  g = { {"uitkijken", "to keep an eye out"}, {"onderzoek", "research, studies"}, {"gelijk", "right (gelijk hebben)"}, {"gevaarlijk", "dangerous"}, {"bericht", "message"} },
},

[5047] = { en = "Finkle Einhorn, At Your Service!", tier = 4,
  t = "Finkle Einhorn, tot je dienst!",
  d = "Je vindt Malyfous Darkhammer in Everlook, $c. Zeg hem: 'Met Finkle is alles oké', en dat het pak perfect werkt.$B$BGeef hem dan dit:$B$B<Finkle geeft je een gloeiend stuk vlees.>$B$BIk heb het uit de ingewanden van het beest gegrist tijdens mijn 'vakantie'.$B$BIk wed dat Malyfous je vrij precies kan vertellen wat hij kan doen met delen van zo'n monster!$B$BO, je weet zeker niet waar Everlook ligt, hè? Naar Winterspring, $gkerel:dame;!",
  o = "Praat met Malyfous Darkhammer in Everlook.",
  p = "Ja?",
  c = "Levend? Werkte het pak? En wat hebben we hier?",
  g = { {"tot je dienst", "at your service"}, {"pak", "suit"}, {"gloeiend", "glowing"}, {"ingewanden", "innards"}, {"gegrist", "snatched (grissen)"}, {"ik wed", "I bet (wedden)"}, {"vrij precies", "fairly accurately"}, {"kerel", "fella"} },
},

[5081] = { en = "Maxwell's Mission", tier = 4,
  t = "De missie van Maxwell",
  d = "Deze informatie vult de gaten in onze verder perfecte kennis over Blackrock Spire.$B$BDe aanval moet beslissend zijn, $N.$B$BEerst moet hun krijgsmeester, de trol Voone, vernietigd worden. Zonder zijn strijdplannen raken de Blackrock-orks in chaos.$B$BDaarna moet je de Highlord van de ogres, Omokk, uitschakelen. De laffe ogres van Blackrock zijn machteloos zonder zijn leiding.$B$BTen slotte de opperheer van de citadel: Wyrmthalak. Als Wyrmthalak dood is, heeft hun centrale commando geen verbinding meer.",
  o = "Reis naar Blackrock Spire en vernietig War Master Voone, Highlord Omokk en Overlord Wyrmthalak. Ga terug naar Marshal Maxwell als het klaar is.",
  p = "Stand van zaken?",
  c = "Uitstekend werk, $N. Je hebt ons op zijn minst meer tijd gegeven - kostbare, kostbare tijd.",
  g = { {"beslissend", "decisive"}, {"krijgsmeester", "war master"}, {"strijdplannen", "battle plans (strijdplan)"}, {"uitschakelen", "to take out"}, {"laffe", "cowardly (laf)"}, {"machteloos", "powerless"}, {"opperheer", "overlord"}, {"stand van zaken", "status"}, {"kostbare", "precious (kostbaar)"}, {"op zijn minst", "at the very least"} },
},

[5089] = { en = "General Drakkisath's Command", tier = 4,
  t = "Het bevel van General Drakkisath",
  d = "Bij het lijk van de verslagen slang vind je iets dat op een belangrijke brief lijkt: een brief van zijn meerdere, General Drakkisath, over de regels die ze moeten volgen.$B$BJe gevoel zegt je dat je hem naar Marshal Maxwell moet brengen.",
  o = "Breng General Drakkisath's Command naar Marshal Maxwell in de Burning Steppes.",
  p = "Wat heb je daar, $N?",
  c = "Het wordt steeds spannender...",
  g = { {"lijk", "corpse"}, {"verslagen", "defeated (verslaan)"}, {"slang", "serpent, snake"}, {"meerdere", "superior"}, {"gevoel", "instinct, feeling"}, {"steeds spannender", "the plot thickens"} },
},

[5102] = { en = "General Drakkisath's Demise", tier = 4,
  t = "De ondergang van General Drakkisath",
  d = "We vechten op twee fronten tegen deze beesten: vanuit onze hoofdstad Stormwind bevechten we ze van binnenuit, en hier, in de Burning Steppes, brengen we de strijd naar hun voordeur. We moeten waakzaam zijn, $N. Niemand mag aan onze woede ontsnappen, want niemand van ons werd gespaard toen zij onze huizen en families aanvielen.$B$BVind die General Drakkisath en vernietig hem!$B$BDe taak zal zeker niet eenvoudig zijn, maar de beloning zal rijk zijn.",
  o = "Reis naar Blackrock Spire en vernietig General Drakkisath. Ga terug naar Marshal Maxwell als het klaar is.$b",
  p = "Is het gedaan?",
  c = "Hierna vallen we vast hun drakenheren aan. Goed gedaan, dappere soldaat van de Alliance! Echt heel goed gedaan.$b",
  g = { {"ondergang", "demise, downfall"}, {"fronten", "fronts (front)"}, {"van binnenuit", "from the inside out"}, {"waakzaam", "vigilant"}, {"woede", "wrath"}, {"ontsnappen", "to escape"}, {"gespaard", "spared (sparen)"}, {"drakenheren", "dragon lords (drakenheer)"}, {"dappere", "brave (dapper)"} },
},

[5127] = { en = "The Demon Forge", tier = 4,
  t = "De demonensmidse",
  d = "Lorax sluit deals, hij neemt ze niet aan van onbelangrijke stervelingen.$B$BToch zal ik met jou een deal sluiten... neem deze piek; hij is gevuld met krachtige Fel-energie. Als je Goraluk Anvilcrack vindt, dood hem dan en steek deze piek door zijn stervende hart. Zijn ziel heeft hij verruild, zijn ziel zal ik krijgen. Breng de piek terug, en het borstharnas dat de dief heeft gestolen, en ik zal je leren wat hij had moeten leren.",
  o = "Reis naar Blackrock Spire en zoek Goraluk Anvilcrack. Dood hem en gebruik dan de Blood Stained Pike op zijn lijk. Nadat zijn ziel is weggezogen, wordt het de Soul Stained Pike.$B$BJe moet ook het Unforged Rune Covered Breastplate vinden.$B$BBreng zowel de Soul Stained Pike als het Unforged Rune Covered Breastplate naar Lorax in Winterspring.",
  p = "Verleid me niet...",
  c = "Ons pact heb je niet verbroken. De ziel heb ik genomen. De beloning zal ik geven.",
  g = { {"demonensmidse", "demon forge"}, {"stervelingen", "mortals (sterveling)"}, {"piek", "pike"}, {"stervende", "dying (sterven)"}, {"verruild", "bartered (verruilen)"}, {"borstharnas", "breastplate"}, {"weggezogen", "siphoned (wegzuigen)"}, {"verleid", "tempt (verleiden)"}, {"pact", "pact"}, {"verbroken", "broken (verbreken)"} },
},

[5160] = { en = "The Matron Protectorate", tier = 4,
  t = "De beschermende matrone",
  d = "Reis naar Kalimdor, $r. Onze vlucht woont in het ijskoude landschap van Winterspring. Als je in Winterspring bent, zoek dan de grotten van Mazthoril.$B$BOp de ijzige vloeren van Mazthoril vind je kobaltblauwe runen. Houd een van mijn schubben vast en ga op een rune staan, dan word je naar Haleh gebracht, onze beschermende matrone.$B$BGeef haar de schub, zodat ze in een visioen kan zien wat ik heb gezien en gevoeld, hier op deze gedoemde plek.",
  o = "Reis naar Winterspring en zoek Haleh. Geef haar Awbee's Scale.",
  p = "Het is goed je te zien, $N.",
  c = "De Aspects eisen dat we ons niet bemoeien met de zaken van stervelingen. Maar in deze wereld is dat niet altijd mogelijk - vooral niet als een van ons zulke regels minachtend negeert.",
  g = { {"matrone", "matron"}, {"ijskoude", "frigid (ijskoud)"}, {"ijzige", "icy (ijzig)"}, {"kobaltblauwe", "cobalt (kobaltblauw)"}, {"schubben", "scales (schub)"}, {"visioen", "vision"}, {"gedoemde", "doomed (gedoemd)"}, {"bemoeien", "to interfere"}, {"minachtend", "contemptuously"}, {"negeert", "disregards (negeren)"} },
},

[5166] = { en = "Breastplate of the Chromatic Flight", tier = 4,
  t = "Het Breastplate of the Chromatic Flight",
  d = "Het smeden van een krachtig borstharnas dat beschermt tegen de genadeloze aanvallen van de chromatische vlucht, berust op ironie.$B$BDe schubben van juist de beesten die we bevechten, moeten worden vastgenaaid op het smetteloze schild van een oude chromatische drake of draak. Op dit moment is er geen enkele bekend, en we moeten hopen dat er nooit een zal bestaan.$B$BTen slotte, misschien wel het moeilijkste onderdeel van allemaal: het bloed van helden.$B$BDe Sculptor moet deze schepping uiteindelijk smeden.",
  o = "Om het Breastplate of the Chromatic Flight te smeden, moet je de volgende voorwerpen naar Jeziba de 'Sculptor' brengen:$B$B1 Chromatic Carapace.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B10 Frayed Abomination Stitchings.",
  p = "Je hebt een wijze keuze gemaakt, $R.",
  c = "Begrijp je het nog steeds niet? De reis was het doel. Voel je de littekens van de strijd niet? De pijn die je hebt doorstaan?$B$BJe hebt de beproeving overleefd, en nu ben je een sterker wezen. Veel sterker. Dit borstharnas is slechts een weerspiegeling van je eigen aangeboren krachten.",
  g = { {"genadeloze", "relentless (genadeloos)"}, {"chromatische", "chromatic (chromatisch)"}, {"berust op", "is built upon (berusten)"}, {"vastgenaaid", "sewn on (vastnaaien)"}, {"smetteloze", "pristine (smetteloos)"}, {"schild", "carapace, shell"}, {"onderdeel", "component"}, {"schepping", "creation"}, {"littekens", "scars (litteken)"}, {"doorstaan", "endured"}, {"beproeving", "ordeal"}, {"weerspiegeling", "reflection"}, {"aangeboren", "innate"} },
},

[5167] = { en = "Legplates of the Chromatic Defier", tier = 4,
  t = "De Legplates of the Chromatic Defier",
  d = "Het schild van een volwassen chromatische drake is nodig als basis voor de beenstukken. Daarna worden briljante chromatische schubben in lagen op het draadframe gelegd en betoverd in het bloed van helden. Ten slotte moet de soepele huid van schaduw op de binnenkant van de scheenplaten worden aangebracht.",
  o = "Om de Legplates of the Chromatic Defier te smeden, moet je de volgende voorwerpen naar Jeziba de 'Sculptor' brengen:$B$B1 Chromatic Carapace.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B5 Skin of Shadow.",
  p = "Zo'n voorwerp is nog nooit gemaakt!",
  c = "Ze zullen hun verwanten ruiken als je hun zalen binnenkomt, $N. Verpletter ze met hun eigen angst!",
  g = { {"volwassen", "mature, adult"}, {"beenstukken", "leggings (beenstuk)"}, {"in lagen", "in layers"}, {"draadframe", "wire frame"}, {"betoverd", "enchanted (betoveren)"}, {"soepele", "supple (soepel)"}, {"scheenplaten", "greaves (scheenplaat)"}, {"aangebracht", "applied (aanbrengen)"}, {"verwanten", "kin (verwant)"}, {"verpletter", "crush (verpletteren)"} },
},

[5306] = { en = "Snakestone of the Shadow Huntress", tier = 4,
  t = "De slangensteen van de schaduwjageres",
  d = "Laat je niet misleiden door haar schoonheid, $c. De schaduwjageres Vosh'gajin is dodelijk en gestoord.$B$B<Kilram wijst naar het litteken op zijn gezicht.>$B$BJa, dat heeft zij me gegeven - een liefdesklapje, noemde ze het.$B$BDe tijd voor wraak is eindelijk gekomen.$B$BJe vindt Vosh'gajin in Blackrock Spire. Dood haar en kom bij me terug met haar slangensteen. Doe dit en ik leer je de kunst van de bijlsmid.",
  o = "Reis naar Blackrock Spire en dood Shadow Hunter Vosh'gajin. Haal Vosh'gajin's Snakestone op en ga terug naar Kilram.",
  p = "Volgens de legende houdt één keer gebruik van Vosh'gajins slangensteen een bijl 1000 jaar vlijmscherp!",
  c = "Kennis is macht!",
  g = { {"slangensteen", "snakestone"}, {"schaduwjageres", "shadow huntress"}, {"misleiden", "to fool, mislead"}, {"gestoord", "deranged"}, {"litteken", "scar"}, {"liefdesklapje", "love tap"}, {"wraak", "vengeance"}, {"bijlsmid", "axesmith"}, {"vlijmscherp", "razor sharp"} },
},

[6502] = { en = "Drakefire Amulet", tier = 4,
  t = "Het Drakefire Amulet",
  d = "Het is een stuk van de draak: een schub, betoverd en veranderd. Heel had het toegang kunnen geven tot het hol van het beest. Gebroken is het nutteloos.$B$BHet voorwerp kan gerepareerd worden, maar daarvoor is het bloed van een kampioen van de zwarte draken nodig. Er is er één... Hij heet General Drakkisath, heerser over de legers van drakenwezens van Nefarian. Misschien heb je van hem gehoord?$B$BKom terug met zijn bloed, $r, en ik zal het stuk betoveren tot iets dat je toegang geeft tot het hol van Onyxia.",
  o = "Je moet het Blood of the Black Dragon Champion halen bij General Drakkisath. Je vindt Drakkisath in zijn troonzaal achter de Halls of Ascension in Blackrock Spire.",
  p = "De tijd stroomt door en gaat niet langzamer, $r. Mijn leven is eeuwig, het jouwe niet. Verspil de tijd niet die je hebt...",
  c = "Dit amulet geeft je de toegang die je zoekt. Het hol van Onyxia ligt in Dustwallow Marsh. Zolang je het amulet hebt, kunnen haar beschermende spreuken je niet tegenhouden.$B$BDe Blue Flight wenst je veel geluk, $N.",
  g = { {"schub", "scale"}, {"betoverd", "enchanted (betoveren)"}, {"toegang", "access"}, {"hol", "lair"}, {"nutteloos", "useless"}, {"kampioen", "champion"}, {"heerser", "ruler"}, {"troonzaal", "throne room"}, {"eeuwig", "eternal"}, {"verspil", "waste (verspillen)"} },
},

[6569] = { en = "Oculus Illusions", tier = 4,
  t = "Oculus-illusies",
  d = "Dus de $r wil een van de Black Flight worden, hè?$B$BDe illusie maken die je nodig hebt is eenvoudig, maar de ingrediënten voor de voorspelling zijn heel moeilijk te krijgen. Rexxar en de Warchief hebben je deze missie toevertrouwd, dus Myranda moet aannemen dat je het kunt.$B$BReis naar de bovenste citadel van Blackrock Spire en dood genoeg zwarte drakenwezens om een van je tassen met hun ogen te vullen.$B$BKom terug naar Myranda als je genoeg van het ingrediënt hebt verzameld.",
  o = "Reis naar Blackrock Spire en verzamel 20 Black Dragonspawn Eyes. Ga terug naar Myranda the Hag als de taak klaar is.",
  p = "De ogen van wat we willen nabootsen, zijn het belangrijkste ingrediënt van elke illusie, $N.$B$B<Myranda wijst naar een tas die bijna overloopt van oogballen, met het label 'Scarlet Crusade'.>$B$B<Myranda lacht.>",
  c = "Laat Myranda eens kijken, $r.$B$BO ja, deze zijn prima.$B$BMet deze ingrediënten maakt Myranda een medaillon voor je. Het geeft een illusie die de poortwachter van de zwarte drakenvlucht kan misleiden.",
  g = { {"illusie", "illusion"}, {"ingrediënten", "components, reagents (ingrediënt)"}, {"voorspelling", "divination"}, {"toevertrouwd", "entrusted (toevertrouwen)"}, {"aannemen", "to assume"}, {"nabootsen", "to mimic"}, {"overloopt", "overflows (overlopen)"}, {"oogballen", "eyeballs (oogbal)"}, {"medaillon", "medallion"}, {"poortwachter", "gatekeeper"}, {"misleiden", "to fool"} },
},

[6821] = { en = "Eye of the Emberseer", tier = 4,
  t = "Het oog van de Emberseer",
  d = "Je hebt me laten zien dat je onze vijanden kunt verslaan en missies kunt uitvoeren voor de zaak van de Waterlords. Maar tot nu toe heb je alleen zwakkere vijanden bevochten... als je tegenover een machtige vijand staat, kun je dan winnen?$B$BDat is je nieuwe taak.$B$BHoog in Blackrock Spire hebben de orks een dienaar van het vuur gevangen, de Pyroguard Emberseer. Zoek de plek waar hij gevangen zit, dood de wezens die hem gevangen houden en dood daarna de Emberseer. Breng me zijn oog, dan laat het me zien wat je waard bent.",
  o = "Breng het Eye of the Emberseer naar Duke Hydraxis in Azshara.",
  p = "Heb je het Oog, $C? Ben je sterk genoeg om Blackrock Spire binnen te gaan?",
  c = "Ah, je bent dus sterk genoeg. En je bent ook slim, want in Blackrock Spire kom je met alleen brute kracht niet ver.$B$BInderdaad, $N, misschien word je nog een waardevolle bondgenoot voor ons...",
  g = { {"verslaan", "to defeat"}, {"uitvoeren", "to carry out"}, {"de zaak", "the cause"}, {"tegenover", "facing, opposite"}, {"dienaar", "servant"}, {"gevangen", "captured (vangen)"}, {"waard", "worth"}, {"brute kracht", "brute strength"}, {"waardevolle", "valued (waardevol)"}, {"bondgenoot", "ally"} },
},

[7761] = { en = "Blackhand's Command", tier = 4,
  t = "Het bevel van Blackhand",
  d = "Sukkel,$B$BIk heb heel weinig vertrouwen in jouw vermogen om buitenstaanders uit het hol van de meester te houden. Voor het zeer waarschijnlijke geval dat je sterft, heeft deze bol een eigen beveiliging. Die voorkomt dat buitenstaanders zich direct naar Blackwing teleporteren.$B$BAlleen wie het Mark of Drakkisath op zijn hand gebrand heeft, kan deze bol gebruiken. Gelukkig is Drakkisath lang niet zo onbekwaam als jij, kwartiermeester. Hij bewaakt het brandijzer zelf!$B$B-Warchief Rend Blackhand$B$BP.S. Vernietig deze brief, idioot.",
  o = "Dat is een heel domme ork. Het lijkt erop dat je dit brandijzer moet vinden en het Mark of Drakkisath moet krijgen om de Orb of Command te kunnen gebruiken.$B$BVolgens de brief bewaakt General Drakkisath het brandijzer. Misschien moet je het onderzoeken.",
  c = "Je krimpt niet eens ineen als het smeulende brandijzer in je huid wordt gedrukt. Wat ben je sterk!$B$BJe hebt nu het Mark of Drakkisath. Veel plezier met het bestormen van het kasteel.",
  g = { {"sukkel", "imbecile, idiot"}, {"vermogen", "ability"}, {"buitenstaanders", "outsiders (buitenstaander)"}, {"beveiliging", "failsafe, security"}, {"gebrand", "branded (branden)"}, {"onbekwaam", "incompetent"}, {"kwartiermeester", "quartermaster"}, {"brandijzer", "branding iron, brand"}, {"krimpt ... ineen", "flinch (ineenkrimpen)"}, {"smeulende", "smouldering (smeulen)"}, {"bestormen", "to storm"} },
},

[7898] = { en = "Thorium Widget", tier = 4,
  t = "Een Thorium Widget",
  p = "Yebb Nebblegear werkt net als ik aan een toekomstige attractie. Volgens Nebb is die attractie zo geweldig dat ze mensen van over de hele wereld zal trekken... en ze zal ons allemaal heel, heel rijk maken!$B$BHij zegt dat hij Thorium Widgets nodig heeft om haar te bouwen, en hij wil dat ik ze voor hem verzamel. Wat zeg je ervan, $N? Weet je waar je Thorium Widgets kunt krijgen? Als je ingenieur bent, kun je ze dan maken? Wil je ze ruilen voor kaartjes van de Darkmoon Faire?",
  c = "Ah, dank je, $N! Yebb zal blij zijn met deze widgets. Ik weet niet wat hij ermee van plan is, maar Yebb is een slimme kleine gnoom. Hij is slim, en misschien een beetje sluw....$B$BAls hij nu maar van de smaak van het vlees van mensachtigen hield... dan zou hij een geweldige trol zijn!$B$BHier, $N. Afspraak is afspraak, en deze kaartjes zijn voor jou.",
  g = { {"toekomstige", "future (toekomstig)"}, {"attractie", "attraction"}, {"trekken", "to draw, attract"}, {"ingenieur", "engineer"}, {"ruilen", "to trade"}, {"kaartjes", "tickets (kaartje)"}, {"sluw", "devious, sly"}, {"mensachtigen", "humanoids (mensachtige)"}, {"afspraak is afspraak", "a deal's a deal"} },
},

[7942] = { en = "More Thorium Widgets", tier = 4,
  t = "Meer Thorium Widgets",
  p = "$N, je bent zo goed voor ons geweest. Je bracht me spullen zonder moe te worden. Je hebt mijn eeuwige dank!$B$BWe hebben niet meer zo veel Thorium Widgets nodig als eerst, maar je mag ze nog steeds bij me brengen. Dan ruil ik ze graag voor kaartjes van de Darkmoon Faire.",
  c = "Alsjeblieft, $N. Hier zijn kaartjes van de Darkmoon Faire, voor je plezier. Geef ze niet allemaal op één plek uit, zoals ze zeggen!",
  g = { {"spullen", "goods, stuff"}, {"eeuwige", "eternal (eeuwig)"}, {"ruil", "trade (ruilen)"}, {"kaartjes", "tickets (kaartje)"}, {"geef ... uit", "spend (uitgeven)"} },
},

[8961] = { en = "Three Kings of Flame", tier = 4,
  t = "Drie vuurkoningen",
  d = "Om Lord Valthalak op te roepen, moeten we eerst de andere twee derde van het amulet verzamelen. Daarvoor hebben we een komfoor nodig en wat speciale kolen om erin te branden.$B$BEr zijn drie edelen van het vuur die hebben wat we nodig hebben: Lord Incendius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire en The Duke of Cynders in Silithus. Haal bij elk van hen een stuk van hun resten. Kom daarna terug naar mij met een Hallowed Brazier. Die kun je kopen bij de Argent Dawn als je bij hen Honored bent.",
  o = "Verzamel de Incendicite of Incendius, de Ember of Emberseer en de Cinder of Cynders, samen met een Hallowed Brazier, en breng ze naar Bodley in Blackrock Mountain.",
  p = "Het was onze dwaasheid... onze ondergang dat we die laatste klus aannamen. Hadden we maar niet per ongeluk de geest van Lord Valthalak gestolen, die in het amulet zat. Waren er maar geen leden in onze huurlingengroep geweest die zo hebzuchtig waren dat ze het onderling verdeelden. Dan was ik nu nog in leven, en dronk ik misschien een biertje, of gooide ik een van mijn kinderen in de lucht.$B$B$N, laat de hebzucht van de laaghartigen in onze oude huurlingenbende niet ook jouw ondergang worden.",
  c = "Ik ben onder de indruk, $C, maar er is geen tijd te verliezen. Ik geef je je volgende taak, want je moet nog een paar belangrijke onderdelen halen voordat we verder kunnen.$B$BPraat weer met me als je denkt dat je klaar bent voor de uitdaging die voor je ligt.",
  g = { {"op te roepen", "to summon (oproepen)"}, {"komfoor", "brazier"}, {"kolen", "coals (kool)"}, {"edelen", "nobles (edele)"}, {"resten", "remains (rest)"}, {"dwaasheid", "folly"}, {"per ongeluk", "inadvertently, by accident"}, {"huurlingengroep", "mercenary group"}, {"hebzuchtig", "greedy"}, {"onderling", "amongst themselves"}, {"laaghartigen", "the ignoble (laaghartig)"}, {"huurlingenbende", "mercenary company"}, {"onder de indruk", "impressed"} },
},

[8966] = { en = "The Left Piece of Lord Valthalak's Amulet", tier = 4,
  t = "Het linkerdeel van het amulet van Lord Valthalak",
  d = "Mijn vriend Mor Grayhoof was de eerste die slachtoffer werd van het bezit van een stuk van het amulet van Lord Valthalak, en van het verdorvende stukje geest dat erin zit. Nadat we het spreukenboek en het amulet van Valthalak hadden gestolen, vluchtten we voor ons leven uit het bovenste deel van Blackrock Spire. Onderweg viel Mor in het onderste deel van de spits.$B$BLater ontdekten we dat hij de val had overleefd, maar alleen om gevangen en gemarteld te worden door War Master Voone. Een paar spookachtige sluipmoordenaars slopen naar binnen en doodden hem vlak voor de ogen van Voone.",
  o = "Gebruik de Brazier of Beckoning om de geest van Mor Grayhoof op te roepen en dood hem. Ga terug naar Bodley in Blackrock Mountain met het Left Piece of Lord Valthalak's Amulet en de Brazier of Beckoning.",
  p = "Is het dan gedaan? Heb je het linkerdeel van het amulet van Lord Valthalak gevonden en de geest van mijn oude makker Mor Grayhoof eindelijk rust gegeven?",
  c = "Je hebt iets groots gedaan, $N. Eén geest rust in vrede, maar er moet nog veel gebeuren voordat we dit allemaal achter ons kunnen laten.$B$BHelaas weet ik niet waar degene is die stierf met het rechterdeel van het amulet in zijn bezit. Maar wees niet bang: tijdens mijn leven hield ik me een beetje bezig met de kunst van het waarzeggen. Daarom heb ik nog een taak voor je, waarmee we het laatste stuk kunnen opsporen.",
  g = { {"slachtoffer", "victim"}, {"bezit", "possession"}, {"verdorvende", "corrupting (verdorven)"}, {"spreukenboek", "spellbook"}, {"vluchtten", "fled (vluchten)"}, {"spits", "spire"}, {"overleefd", "survived (overleven)"}, {"gemarteld", "tortured (martelen)"}, {"spookachtige", "spectral (spookachtig)"}, {"sluipmoordenaars", "assassins (sluipmoordenaar)"}, {"slopen", "snuck (sluipen)"}, {"makker", "companion, mate"}, {"waarzeggen", "divination, fortune-telling"}, {"opsporen", "to ferret out, track down"} },
},

[8989] = { en = "The Right Piece of Lord Valthalak's Amulet", tier = 4,
  t = "Het rechterdeel van het amulet van Lord Valthalak",
  d = "Mijn vriend Mor Grayhoof was de eerste die slachtoffer werd van het bezit van een stuk van het amulet van Lord Valthalak, en van het verdorvende stukje geest dat erin zit. Nadat we het spreukenboek en het amulet van Valthalak hadden gestolen, vluchtten we voor ons leven uit het bovenste deel van Blackrock Spire. Onderweg viel Mor in het onderste deel van de spits.$B$BLater ontdekten we dat hij de val had overleefd, maar alleen om gevangen en gemarteld te worden door War Master Voone. Een paar spookachtige sluipmoordenaars slopen naar binnen en doodden hem vlak voor de ogen van Voone.",
  o = "Gebruik de Brazier of Beckoning om de geest van Mor Grayhoof op te roepen en dood hem. Ga terug naar Bodley in Blackrock Mountain met het weer samengevoegde Lord Valthalak's Amulet en de Brazier of Beckoning.",
  p = "Is het dan gedaan? Heb je het rechterdeel van het amulet van Lord Valthalak gevonden, het amulet weer tot één geheel samengevoegd en de geest van mijn oude makker Mor Grayhoof eindelijk rust gegeven?",
  c = "Dank je dat je Mor Grayhoof hebt geholpen, $N. Weer een geest rust in vrede, en we hebben nu het weer samengevoegde amulet! Maar de zwaarste test ligt nog voor ons.$B$BHet komfoor moet worden afgestemd op het oproepen van Lord Valthalak. Daarvoor moeten er nog een paar voorwerpen verzameld en hier bij mij gebracht worden.",
  g = { {"slachtoffer", "victim"}, {"bezit", "possession"}, {"verdorvende", "corrupting (verdorven)"}, {"spreukenboek", "spellbook"}, {"vluchtten", "fled (vluchten)"}, {"spits", "spire"}, {"overleefd", "survived (overleven)"}, {"gemarteld", "tortured (martelen)"}, {"spookachtige", "spectral (spookachtig)"}, {"sluipmoordenaars", "assassins (sluipmoordenaar)"}, {"slopen", "snuck (sluipen)"}, {"makker", "companion, mate"}, {"samengevoegd", "recombined (samenvoegen)"}, {"zwaarste", "hardest (zwaar)"}, {"afgestemd", "attuned (afstemmen)"}, {"komfoor", "brazier"} },
},

})

